# area: generics_variance
# hypothesis: A PEP 695 class that keeps its Callable[[T], None] in a dict and exposes it through a property setter should reject Handler[float] where Handler[int] is expected, yet if accepted the int-only callback is later called with 1.5 and fails with AttributeError at runtime.
from collections.abc import Callable
from typing import reveal_type


class Handler[T]:
    def __init__(self, cb: Callable[[T], None]) -> None:
        self._slots: dict[str, Callable[[T], None]] = {'cb': cb}

    @property
    def cb(self) -> Callable[[T], None]:
        return self._slots['cb']

    @cb.setter
    def cb(self, value: Callable[[T], None]) -> None:
        self._slots['cb'] = value


def use(h: Handler[int]) -> None:
    h.cb = lambda v: print(v.bit_length())


def probe() -> str:
    hf = Handler[float](lambda x: print(x.is_integer()))
    use(hf)  # expect-error: Handler[float] is not Handler[int]
    reveal_type(hf.cb)
    try:
        hf.cb(1.5)
    except AttributeError:
        return 'AttributeError'
    return 'ok'


print(probe())
